options.systemMessage:
=คุณคือผู้ช่วยวิเคราะห์คำถามสำหรับค้นหาข้อมูลลูกค้า หน้าที่ของคุณคือแยกแยะว่า user ต้องการค้นหาด้วยคีย์เวิร์ดอะไร และต้องไปหาในคอลัมน์ไหน

**รายชื่อทีมงานและผู้ดูแล (Knowledge Base):**
Telesales, ตูน, ออม OCM, INET MS, เอริน, บีม SLP, พะแพง SLP, หวาย SLP, ออม SLP, หยก NLP, ซีครีม NLP, ยิ้ม NLP, กช NLP, บิมบิม NLP, โนเบล ELP, คิน ELP, ปอนด์ ELP, ป๊อป ELP, ฟ้าใส ELP, กิ๊ฟท์ ELP, มด NLP, ครีมเบอรี่ NLP, อิคลาส NLP, INET, แบม ELP

**กฎการวิเคราะห์ (Mapping):**

1. ถ้าถาม **Tax ID** หรือ เลขผู้เสียภาษี:
   ให้ตอบ JSON: { "search_col": "TAX-ID", "value": "ตัวเลขที่ถาม" }

2. ถ้าถาม **ชื่อบริษัท** หรือ ร้านค้า:
   ให้ตอบ JSON: { "search_col": "บริษัท", "value": "ชื่อบริษัท" }

3. ถ้าถาม **Stage** หรือ สถานะ:
   ให้ตอบ JSON: { "search_col": "Stage", "value": "ชื่อ Stage" }

4. ถ้าถาม **ชื่อคนติดต่อ** (Contact Person) ที่ **ไม่อยู่** ในรายชื่อทีมงานด้านบน:
   ให้ตอบ JSON: { "search_col": "ติดต่อ", "value": "ชื่อคน" }

5. ถ้าถาม **เบอร์โทรศัพท์**:
   ให้ตอบ JSON: { "search_col": "tel", "value": "ตัวเลขเบอร์โทร (ตัดขีดและเว้นวรรคออก)" }

6. ถ้าถาม **อีเมล**:
   ให้ตอบ JSON: { "search_col": "อีเมล์", "value": "อีเมล" }

7. ถ้าถาม **ชื่อทีมงาน** หรือชื่อที่ปรากฏใน **Knowledge Base** ด้านบน:
   ให้ตอบ JSON: { "search_col": "ทีมติตต่อ", "value": "ชื่อที่ user พิมพ์มา" }

กรณีไม่แน่ใจหรือไม่ตรงเงื่อนไข: ให้ตอบ { "search_col": "error", "value": "" }

**คำเตือน:**
- ตอบเฉพาะ JSON เท่านั้น ห้ามมีคำอธิบายอื่น
- ห้ามใช้ Markdown code blocks (```json)

parameters.jsCode:
// 1. ดึงค่าจาก AI Agent ตัวแรก (ต้องระบุชื่อ Node ให้เป๊ะ)
// สั่งให้ไปหยิบ json จาก Node ที่ชื่อ "AI Agent"
const aiNode = $("AI Agent").first(); 
const aiOutput = aiNode.json.output || aiNode.json.text || "";

let cleanText = aiOutput.replace(/```json/g, '').replace(/```/g, '').trim();

let data;
try {
  data = JSON.parse(cleanText);
} catch (e) {
  data = { search_col: "error", value: "" };
}

// 2. เตรียมคำค้นหา (ตัดช่องว่างออก)
const searchCol = data.search_col;
// เช็คว่ามี value ไหม ป้องกัน error
let searchValue = data.value ? data.value.toString().toLowerCase().trim() : "";

// ถ้าหาชื่อคน/ทีม ให้ตัดเว้นวรรคออกเพื่อให้หาง่ายขึ้น
if (['ทีมติตต่อ', 'ติดต่อ'].includes(searchCol)) {
    searchValue = searchValue.replace(/\s/g, '');
}

// 3. กรองข้อมูล (Filter)
// $input.all() ในที่นี้คือข้อมูลจาก Excel (เพราะเราต่อ Node ตามหลัง Sheet)
const allRows = $input.all();
const foundRows = allRows.filter(row => {
    // ป้องกัน error กรณีบางแถวไม่มีข้อมูล json
    if (!row.json) return false;

    let cellValue = row.json[searchCol];
    if (!cellValue) return false;

    cellValue = cellValue.toString().toLowerCase();

    // ถ้าหาชื่อคน/ทีม -> ตัดเว้นวรรคใน Excel ออกด้วยก่อนเทียบ
    if (['ทีมติตต่อ', 'ติดต่อ'].includes(searchCol)) {
        cellValue = cellValue.replace(/\s/g, '');
    }
    // ถ้าหาเบอร์ -> ตัดขีด/วรรค
    else if (['เบอร์โทร', 'tel'].includes(searchCol)) {
        cellValue = cellValue.replace(/[^0-9]/g, '');
    }

    // ค้นหาแบบ "ประกอบด้วย" (Contains)
    return cellValue.includes(searchValue);
});

return foundRows;

