// 1. ดึงค่าจาก AI Agent ตัวแรก (ต้องระบุชื่อ Node ให้เป๊ะ)
// สั่งให้ไปหยิบ json จาก Node ที่ชื่อ "AI Agent"
const aiNode = $("AI Agent2").first(); 
const aiOutput = aiNode.json.output || aiNode.json.text || "";

let cleanText = aiOutput.replace(/```json/g, '').replace(/```/g, '').trim();

let data;
try {
  data = JSON.parse(cleanText);
} catch (e) {
  data = { search_col: "error", value: "" };
}

// 2. เตรียมคำค้นหา (ตัดช่องว่างออก)
const searchCol = data.search_col;
// เช็คว่ามี value ไหม ป้องกัน error
let searchValue = data.value ? data.value.toString().toLowerCase().trim() : "";

// ถ้าหาชื่อคน/ทีม ให้ตัดเว้นวรรคออกเพื่อให้หาง่ายขึ้น
if (['ทีมติตต่อ', 'ติดต่อ'].includes(searchCol)) {
    searchValue = searchValue.replace(/\s/g, '');
}

// 3. กรองข้อมูล (Filter)
// $input.all() ในที่นี้คือข้อมูลจาก Excel (เพราะเราต่อ Node ตามหลัง Sheet)
const allRows = $input.all();
const foundRows = allRows.filter(row => {
    // ป้องกัน error กรณีบางแถวไม่มีข้อมูล json
    if (!row.json) return false;

    let cellValue = row.json[searchCol];
    if (!cellValue) return false;

    cellValue = cellValue.toString().toLowerCase();

    // ถ้าหาชื่อคน/ทีม -> ตัดเว้นวรรคใน Excel ออกด้วยก่อนเทียบ
    if (['ทีมติตต่อ', 'ติดต่อ'].includes(searchCol)) {
        cellValue = cellValue.replace(/\s/g, '');
    }
    // ถ้าหาเบอร์ -> ตัดขีด/วรรค
    else if (['เบอร์โทร', 'tel'].includes(searchCol)) {
        cellValue = cellValue.replace(/[^0-9]/g, '');
    }

    // ค้นหาแบบ "ประกอบด้วย" (Contains)
    return cellValue.includes(searchValue);
});

return foundRows;

// ==========================================
// ส่วนตั้งค่า (CONFIGURATION)
// ==========================================

// 1. รายชื่อผู้มีสิทธิ์ใช้งาน (Whitelist User IDs)
const ALLOWED_USERS = [
    "U226d26484e6f2c7b4a9bc2f54a2d0cbb", // <-- USER ID ของคุณ (แก้ไขแล้ว)
    "U39ad8f7118178f72fa5a8dde0b1c59xx"  // <-- เพิ่ม ID เพื่อนร่วมทีมตรงนี้
];

// ดึงข้อมูลพื้นฐานจาก Webhook
// **ต้องเช็คชื่อ Node Webhook ให้ตรง (ในที่นี้คือ Webhook1)**
const webhookData = $('Webhook1').item.json.body.events[0]; 
const replyToken = webhookData.replyToken;
const currentUserId = webhookData.source.userId;

// ==========================================
// FEATURE 1: ระบบความปลอดภัย (SECURITY CHECK)
// ==========================================
if (!ALLOWED_USERS.includes(currentUserId)) {
    return {
        "replyToken": replyToken,
        "messages": [{
            "type": "flex",
            "altText": "Access Denied",
            "contents": {
                "type": "bubble",
                "styles": { "body": { "backgroundColor": "#333333" } },
                "body": {
                    "type": "box",
                    "layout": "vertical",
                    "contents": [
                        { "type": "text", "text": "🔒 Access Denied", "weight": "bold", "size": "lg", "color": "#FF5555", "align": "center" },
                        { "type": "text", "text": "คุณไม่มีสิทธิ์เข้าถึงข้อมูลนี้\nกรุณาติดต่อ Admin เพื่อลงทะเบียน", "size": "xs", "color": "#CCCCCC", "align": "center", "margin": "md", "wrap": true }
                    ]
                }
            }
        }]
    };
}

// ==========================================
// PREPARE DATA & NULL CHECK
// ==========================================
const items = $input.all();

// ฟังก์ชันช่วยเช็คค่า (ถ้าไม่มีข้อมูล ให้ข้าม หรือแสดงขีด)
const has = (val) => val && val.toString().trim() !== "" && val.toString().trim() !== "-";
const check = (val) => has(val) ? val.toString() : "-";


// ==========================================
// FEATURE 2: แจ้งเตือนเมื่อไม่พบข้อมูล (NOT FOUND)
// ==========================================
if (items.length === 0 || !items[0].json) {
    return {
        "replyToken": replyToken,
        "messages": [{
            "type": "flex",
            "altText": "ไม่พบข้อมูล",
            "contents": {
                "type": "bubble",
                "styles": { "body": { "backgroundColor": "#FFF5F5" } }, 
                "body": {
                    "type": "box",
                    "layout": "vertical",
                    "contents": [
                        { "type": "text", "text": "❌ ไม่พบข้อมูล", "weight": "bold", "size": "lg", "color": "#D32F2F", "align": "center" },
                        { "type": "text", "text": "ไม่พบรายชื่อหรือเบอร์โทรนี้ในระบบ\nลองค้นหาด้วยคำอื่นดูนะครับ", "size": "xs", "color": "#666666", "align": "center", "margin": "md", "wrap": true }
                    ]
                }
            }
        }]
    };
}

// ==========================================
// FEATURE 3: สร้างการ์ดแบบสไลด์ (CAROUSEL)
// ==========================================
const bubbles = [];

// วนลูปสร้างการ์ดทีละใบ
items.forEach(item => {
    const customer = item.json;

    // สร้างส่วนเนื้อหา (Body Rows)
    let bodyContents = [];

    // ** THE COMPACT FIX: margin เป็น "sm" **
    const addRow = (label, value) => {
        if (has(value)) {
            bodyContents.push({
                "type": "box", "layout": "baseline", "margin": "sm", // FIX: ลดพื้นที่ว่าง
                "contents": [
                    { "type": "text", "text": label, "color": "#aaaaaa", "size": "sm", "flex": 2 },
                    { "type": "text", "text": value.toString(), "wrap": true, "color": "#666666", "size": "sm", "flex": 4 }
                ]
            });
        }
    };

    const company = check(customer['บริษัท']);
    const taxId = customer['TAX-ID'];
    const contact = check(customer['ติดต่อ']);
    const phone = customer['เบอร์โทร'] || customer['tel'];
    const email = check(customer['อีเมล์']);
    const stage = check(customer['Stage']);
    const note = customer['Remark'] || customer['รายละเอียด'] || customer['Note'];

    if (has(taxId)) addRow("🆔 Tax ID", taxId);
    addRow("👤 ผู้ติดต่อ", contact);
    addRow("📞 เบอร์โทร", phone);
    addRow("📧 อีเมล", email);
    addRow("🚦 สถานะ", stage);

    // หมายเหตุ
    if (has(note)) {
        bodyContents.push(
            { "type": "separator", "margin": "lg" },
            { "type": "text", "text": "📝 หมายเหตุ:", "margin": "md", "weight": "bold", "size": "xs", "color": "#333333" },
            { "type": "text", "text": note.toString(), "wrap": true, "size": "xs", "color": "#888888", "margin": "sm" }
        );
    }

    // ปุ่มโทรออก (Footer)
    let footerContents = [];
    if (has(phone)) {
        let cleanPhone = phone.toString().replace(/[^0-9]/g, '');
        footerContents.push({
            "type": "button", "style": "primary", "color": "#1DB446", "height": "sm",
            "action": { "type": "uri", "label": "📞 โทรออก", "uri": `tel:${cleanPhone}` }
        });
    }

    // ประกอบร่าง Bubble 1 ใบ
    bubbles.push({
        "type": "bubble",

        "header": {
            "type": "box", "layout": "vertical", "backgroundColor": "#f7f7f7",
            "contents": [
                { "type": "text", "text": "CRM RESULT", "color": "#1DB446", "weight": "bold", "size": "xxs" },
                { "type": "text", "text": company, "weight": "bold", "size": "lg", "margin": "sm", "wrap": true } 
            ]
        },
        // ** THE COMPACT FIX: เพิ่ม spacing: "sm" ที่ Body **
        "body": { "type": "box", "layout": "vertical", "spacing": "sm", "contents": bodyContents }, 
        "footer": { "type": "box", "layout": "vertical", "contents": footerContents }
    });
});

// ==========================================
// ส่งผลลัพธ์ (RETURN JSON)
// ==========================================
return {
    "replyToken": replyToken,
    "messages": [{
        "type": "flex",
        "altText": `พบข้อมูลลูกค้า ${bubbles.length} รายการ`,
        "contents": {
            "type": "carousel", 
            "contents": bubbles
        }
    }]
};
